actions.script:
const out = ec.service.sync().name('org.moqui.maps.MapServices.get#EffectiveConfig').requireNewTransaction(true)
    .parameters({profileId: profileId || null, layerIds: layerIds || null, recordLayers: false}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse(out.config || {})

const access = ec.service.sync().name('org.moqui.maps.MapSourceServices.get#SourceAccess')
    .parameters({layerId: String(layerId ?? ''), revision: String(revision ?? '')}).call()
if (ec.message.hasError() || !access?.ok) {
    const status = ec.message.hasError() ? 404 : Number(access.status) || 404
    ec.message.clearErrors()
    ec.web.sendJsonError(status, status === 409 ? 'The map archive changed: load the map again' : 'Map archive not available')
} else {
    // the caller was checked above; the storage's rows (DbResource, git) are read as the framework
    const wasDisabled = ec.artifactExecution.disableAuthz()
    try { ec.web.sendPinnedResourceResponse(access.location, access.tag, access.size, true, access.fileName) }
    finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
}

const blank = value => value == null || String(value).trim() === ''
let key = null
try { key = typeof recordKey === 'string' ? JSON.parse(recordKey) : recordKey } catch (err) { key = null }
const lat = Number(String(latitude ?? '').trim()), lon = Number(String(longitude ?? '').trim())
if (blank(adapterKey) || !key || typeof key !== 'object' || Array.isArray(key)) {
    ec.message.addError(ec.l10n.localize('This record\'s location cannot be changed here'))
} else if (blank(latitude) || blank(longitude) || !(lat >= -90 && lat <= 90) || !(lon >= -180 && lon <= 180)) {
    ec.message.addError(ec.l10n.localize('Choose a point on the map, or enter a latitude from -90 to 90 and a longitude from -180 to 180'))
} else {
    // the adapter and its write as a probe: a refusal by authorization is the same words as the adapter's own, and
    // what the adapter or the registry said is not passed on or logged, only the adapter's key
    let stored = null
    let failed = false
    ec.message.pushErrors()
    try {
        const resolved = ec.service.sync().name('org.moqui.maps.MapServices.get#AdapterService')
            .parameters({adapterKey: String(adapterKey), operation: 'store'}).call()
        if (!ec.message.hasError()) stored = ec.service.sync().name(resolved.serviceName).parameters({recordKey: key,
            addressPurpose: addressPurpose || null, recordVersion: blank(recordVersion) ? '0' : String(recordVersion),
            point: {longitude: lon, latitude: lat}}).call()
        failed = ec.message.hasError()
    } catch (err) {
        failed = true
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    if (failed) {
        ec.logger.warn('Map adapter ' + String(adapterKey).slice(0, 60) + ' did not store a location')
        ec.message.addError(ec.l10n.localize('You may not change this record\'s location'))
    } else if (stored?.applied) ec.message.addMessage(ec.l10n.localize('The location is saved'), 'success')
    else ec.message.addError(stored?.reason || ec.l10n.localize('The location was not saved'))
}
// a background post (every client's: the form says background-submit) is answered with its words: a refusal as an
// error status, so the dialog stays open with it, and a save as its message, so the page behind reloads
const asJson = String(ec.web?.request?.getHeader('Accept') ?? '').includes('application/json')
if (asJson && ec.message.hasError()) {
    const refusal = ec.message.getErrorsString()
    ec.message.clearErrors()
    ec.web.sendJsonError(409, refusal)
} else if (asJson) {
    ec.message.clearAll()
    ec.web.sendJsonResponse({messageInfos: [{message: ec.l10n.localize('The location is saved'), type: 'success'}]})
}

record = mapConfig.record || null
recordError = Array.from(mapConfig.layerErrors || []).find(error => error.id === 'record') || null
const recordPoint = Array.from(mapConfig.points || []).find(point => point.id === 'record') || null
const num = value => {
    const text = String(value ?? '').trim()
    const found = text ? Number(text) : NaN
    return Number.isFinite(found) ? found : null
}
const plainLon = num(longitude), plainLat = num(latitude)
const plain = !adapterKey && plainLon !== null && plainLat !== null && plainLon >= -180 && plainLon <= 180 && plainLat >= -90 && plainLat <= 90
// a plain postal code's one match (several are choices this dialog does not make: it says so)
const postalMatches = Array.from(postal?.matches || [])
const postalMatch = !adapterKey && !plain && postalMatches.length === 1 ? postalMatches[0] : null
postalNote = !adapterKey && !plain && postalCode ? (postalMatches.length > 1 ? ec.l10n.localize('More than one postal area has this code: choose one in Maps')
    : !postalMatch ? (postal?.reason || ec.l10n.localize('No imported Geo data has this postal code')) : '') : ''
// an approximate place (a postal area) says so in words, in every mode
approximateText = record?.approximate ? record.precisionText : postalMatch ? postalMatch.precisionText : ''
placeNamesText = postalMatch && (postalMatch.placeNames || []).length ? ec.l10n.localize('Places with this code') + ': '
    + postalMatch.placeNames.map(place => place.name + (place.adminName1 ? ' (' + place.adminName1 + ')' : '')).join(', ') : ''
place = recordPoint ? {id: 'record', lon: Number(recordPoint.lon), lat: Number(recordPoint.lat), label: record?.label || recordPoint.label || '',
        precisionEnumId: record?.approximate ? null : record?.precisionEnumId || null, precision: record?.approximate ? record.precisionText : null,
        sourceText: record?.sourceText || null}
    : plain ? {id: 'place', lon: plainLon, lat: plainLat, label: String(label || '')}
    : postalMatch ? {id: 'place', lon: Number(postalMatch.lon), lat: Number(postalMatch.lat), label: String(label || '') || postalMatch.displayCode,
        precision: postalMatch.precisionText, sourceText: postalMatch.sourceText} : null
placePoints = place ? [place] : []
// the record's view (a postal area's extent, else its point and zoom) and its area or line, when it is not a point
mapExtent = postalMatch && Array.isArray(postalMatch.extent) ? postalMatch.extent.join(',')
    : Array.isArray(mapConfig.extent) && mapConfig.extent.length === 4 ? mapConfig.extent.join(',') : ''
// a plain point is the view too, so the profile's own view does not win over it
mapCenter = mapExtent ? '' : adapterKey && Array.isArray(mapConfig.center) ? mapConfig.center.join(',')
    : place ? place.lon + ',' + place.lat : ''
mapZoom = !mapCenter ? '' : adapterKey ? (mapConfig.zoom != null ? String(mapConfig.zoom) : '') : '14'
const areas = Array.from(mapConfig.features?.features || []).filter(feature => feature?.id === 'record')
recordFeatures = areas.length ? {type: 'FeatureCollection', features: areas} : null
hideId = /^[A-Za-z][A-Za-z0-9_-]{0,80}$/.test(String(dialogId || '')) ? String(dialogId) : 'LocalMapDialog'
mayChoose = !!record && Array.from(record.permittedActions || []).includes('chooseLocation')
pickPlain = !adapterKey && String(pick || '') === 'true'
// the user's own grant of the app, not the frames of an app that shows this dialog under its own root
mayOpenMaps = !!ec.user.userId && !!ec.artifactExecution.isPermittedOwn('component://tools/screen/Maps.xml', 'AT_XML_SCREEN', 'view')
placeTitle = record?.label || (place ? place.label : '') || ec.l10n.localize('Place')
const keyText = recordKey == null ? '' : typeof recordKey === 'string' ? recordKey : JSON.stringify(recordKey)
storeValues = {adapterKey: adapterKey || '', recordKey: keyText, addressPurpose: addressPurpose || '', recordVersion: record?.recordVersion || '',
    latitude: place ? place.lat.toFixed(6) : '', longitude: place ? place.lon.toFixed(6) : ''}
openParameters = adapterKey ? {adapterKey, recordKey: keyText, addressPurpose: addressPurpose || ''}
    : place ? {longitude: String(place.lon), latitude: String(place.lat), label: place.label} : {}
